insert into public.sample_templates (id, project_name, manual_text, parts, steps, model_path)
values ('bookshelf', $name$Sample: 3-shelf bookshelf$name$, $manual$Step 1: Lay out the bottom panel and dowels.
Place the bottom panel on a soft surface and push the eight wooden dowels into the pre-drilled holes.

Step 2: Attach the left side.
Slide the left side panel onto the dowels until it sits flush with the bottom panel.

Step 3: Attach the right side.
Repeat on the right: line up the holes and press the right side panel onto the dowels.

Step 4: Add the top panel.
Lower the top panel onto the upper dowels so both sides are held in place.
WARNING: Two people recommended to keep the frame steady.

Step 5: Lock the joints.
Insert the eight cam locks and turn each one clockwise about half a turn until the joint is tight.
WARNING: Do not overtighten the cam locks.

Step 6: Place the shelves.
Rest the three shelves on the shelf pins, starting with the lowest one.

Step 7: Fix the back panel.
Lay the back panel on the rear of the frame and nail it along the edges.
WARNING: Anchor the bookshelf to the wall to prevent tipping.$manual$, $json$[{"id":"side_left","label":"side left","size":[0.018,1.2,0.3],"center":[-0.391,0.6,0]},{"id":"side_right","label":"side right","size":[0.018,1.2,0.3],"center":[0.391,0.6,0]},{"id":"bottom","label":"bottom","size":[0.764,0.018,0.3],"center":[0,0.05,0]},{"id":"top","label":"top","size":[0.764,0.018,0.3],"center":[0,1.191,0]},{"id":"shelf_1","label":"shelf 1","size":[0.764,0.018,0.28],"center":[0,0.33,0.01]},{"id":"shelf_2","label":"shelf 2","size":[0.764,0.018,0.28],"center":[0,0.62,0.01]},{"id":"shelf_3","label":"shelf 3","size":[0.764,0.018,0.28],"center":[0,0.91,0.01]},{"id":"back_panel","label":"back panel","size":[0.8,1.2,0.004],"center":[0,0.6,-0.152]},{"id":"dowel_1","label":"dowel 1","size":[0.03,0.008,0.008],"center":[-0.377,0.05,-0.1]},{"id":"cam_lock_1","label":"cam lock 1","size":[0.015,0.012,0.015],"center":[-0.347,0.059,-0.07]},{"id":"dowel_2","label":"dowel 2","size":[0.03,0.008,0.008],"center":[-0.377,0.05,0.1]},{"id":"cam_lock_2","label":"cam lock 2","size":[0.015,0.012,0.015],"center":[-0.347,0.059,0.13]},{"id":"dowel_3","label":"dowel 3","size":[0.03,0.008,0.008],"center":[0.377,0.05,-0.1]},{"id":"cam_lock_3","label":"cam lock 3","size":[0.015,0.012,0.015],"center":[0.347,0.059,-0.07]},{"id":"dowel_4","label":"dowel 4","size":[0.03,0.008,0.008],"center":[0.377,0.05,0.1]},{"id":"cam_lock_4","label":"cam lock 4","size":[0.015,0.012,0.015],"center":[0.347,0.059,0.13]},{"id":"dowel_5","label":"dowel 5","size":[0.03,0.008,0.008],"center":[-0.377,1.191,-0.1]},{"id":"cam_lock_5","label":"cam lock 5","size":[0.015,0.012,0.015],"center":[-0.347,1.2,-0.07]},{"id":"dowel_6","label":"dowel 6","size":[0.03,0.008,0.008],"center":[-0.377,1.191,0.1]},{"id":"cam_lock_6","label":"cam lock 6","size":[0.015,0.012,0.015],"center":[-0.347,1.2,0.13]},{"id":"dowel_7","label":"dowel 7","size":[0.03,0.008,0.008],"center":[0.377,1.191,-0.1]},{"id":"cam_lock_7","label":"cam lock 7","size":[0.015,0.012